mkdir -p ~/lab/oom && cd ~/lab/oom
cat > Zjadacz.java <<'EOF'
import java.util.*;
public class Zjadacz {
  public static void main(String[] a) throws Exception {
    List<byte[]> l = new ArrayList<>();
    for (int i = 0; i < 60; i++) { l.add(new byte[10 << 20]); java.util.Arrays.fill(l.get(i), (byte) 1); }
    System.out.println("zajeto " + l.size() * 10 + " MB");
  }
}
EOF
docker run --name oom-test -m 256m -v "$PWD:/app" -w /app eclipse-temurin:21-jdk java -Xmx1g Zjadacz.java
docker inspect -f 'kod={{.State.ExitCode}} OOMKilled={{.State.OOMKilled}}' oom-test
docker rm oom-test > /dev/null
